solutions.java:
import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StringTokenizer st = new StringTokenizer(new String(System.in.readAllBytes()));
        long n = Long.parseLong(st.nextToken());
        long s = (long) Math.sqrt((double) n);
        while (s * s > n) s--;
        while ((s + 1) * (s + 1) <= n) s++;
        long t = 0;
        for (long i = 1; i <= s; i++) t += n / i;
        System.out.println(2 * t - s * s);
    }
}
